import argparse
import json
import logging
import os
import sys
from datetime import datetime
from urllib.parse import urlparse
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError

def process_url(url):
    try:
        req = Request(url, timeout=5)
        with urlopen(req) as response:
            return response.getcode()
    except HTTPError as e:
        return f"ERROR: {str(e)}"
    except URLError as e:
        return f"ERROR: {str(e)}"
    except Exception as e:
        return f"ERROR: {str(e)}"

def main():
    parser = argparse.ArgumentParser(description='Check URLs and log results.')
    parser.add_argument('input_file', type=str, help='Path to the text file containing URLs')
    args = parser.parse_args()

    with open(args.input_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    results = {}
    for url in urls:
        status_or_error = process_url(url)
        results[url] = {
            'status': status_or_error if isinstance(status_or_error, int) else None,
            'error': status_or_error if isinstance(status_or_error, str) and status_or_error.startswith('ERROR:') else None
        }

    print(json.dumps(results))

    with open('check.log', 'a') as f:
        for url in urls:
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            status_or_error = process_url(url)
            line = f"{timestamp} {url} {status_or_error}\n"
            f.write(line)

if __name__ == "__main__":
    main()

import sys
import json
import requests
from datetime import datetime
from urllib.parse import urlparse

def check_url(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code
    except requests.exceptions.RequestException as e:
        return str(e)

def main():
    if len(sys.argv) != 2:
        print("Usage: python link_check.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    url_results = {}

    try:
        with open(file_path, 'r') as file:
            for line in file:
                url = line.strip()
                if not url:
                    continue
                url_results[url] = check_url(url)
    except IOError as e:
        print(f"Error reading file: {e}")
        sys.exit(1)

    # Print JSON output
    print(json.dumps(url_results))

    # Append to check.log
    log_file = "check.log"
    with open(log_file, 'a') as log:
        for url, result in url_results.items():
            timestamp = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
            log.write(f"{timestamp} {url} {result}\n")

if __name__ == "__main__":
    main()

import sys
import json
import requests
from datetime import datetime
import os

def main():
    probe_log = "probe.log"
    results = {}

    for line in sys.stdin:
        url = line.strip()
        if not url:
            continue

        try:
            response = requests.get(url, timeout=5)
            status_code = response.status_code

            if 100 <= status_code < 400:
                results[url] = status_code
            elif 400 <= status_code < 600:
                results[url] = response.text
            else:
                results[url] = f"Status code {status_code} (ignored)"

        except requests.exceptions.RequestException as e:
            results[url] = str(e)

        # Append to log
        timestamp = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        with open(probe_log, "a") as f:
            f.write(f"{timestamp} {url} {results[url]}\n")

    # Print JSON output
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

import sys
import requests
from datetime import datetime
import os

def clean_text(text):
    return text.replace('\n', ' ').replace('\r', ' ')

def probe_url(url):
    try:
        response = requests.get(url, timeout=5)
        return str(response.status_code)
    except requests.exceptions.RequestException as e:
        return clean_text(str(e))

def main():
    log_file = 'probe.log'
    with open(log_file, 'a') as log:
        for url in sys.stdin:
            url = url.strip()
            if not url:
                continue

            status = probe_url(url)
            print(f"{url} {status}")

            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_line = f"{timestamp} {url} {status}\n"
            log.write(log_line)

if __name__ == "__main__":
    main()

import sys
import requests
import datetime

# Function to probe URLs
def probe_urls():
    for line in sys.stdin:
        url = line.strip()
        if not url:
            continue
        try:
            response = requests.get(url, timeout=5)
            status_code = response.status_code
        except Exception as e:
            status_code = str(e).replace('\n', ' ')
        print(f'{url} {status_code}')
        log_result(url, status_code)

# Function to log results
def log_result(url, status_code):
    current_time = datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
    with open('probe.log', 'a') as log_file:
        log_file.write(f'{current_time} {url} {status_code}\n')

if __name__ == '__main__':
    probe_urls()

